import{_ as r,o as n,c as i,ah as s}from"./chunks/framework.DDXs_i7t.js";const c=JSON.parse('{"title":"Rechercheeintrag: Das tragische Schicksal der Familie Alsberg – Die menschlichen Kosten der \\"Arisierung\\" und die Rolle Helmut Hortens","description":"Eine tiefgehende Recherche über die jüdische Unternehmerfamilie Alsberg, ihre Kaufhäuser, die brutale \\"Arisierung\\" durch die Nationalsozialisten und das individuelle Leid ihrer Mitglieder.","frontmatter":{"title":"Rechercheeintrag: Das tragische Schicksal der Familie Alsberg – Die menschlichen Kosten der \\"Arisierung\\" und die Rolle Helmut Hortens","description":"Eine tiefgehende Recherche über die jüdische Unternehmerfamilie Alsberg, ihre Kaufhäuser, die brutale \\"Arisierung\\" durch die Nationalsozialisten und das individuelle Leid ihrer Mitglieder.","date":"2026-02-27T00:00:00.000Z"},"headers":[],"relativePath":"logbuch/2026-02-27-alsberg-familie.md","filePath":"logbuch/2026-02-27-alsberg-familie.md"}'),t={name:"logbuch/2026-02-27-alsberg-familie.md"};function a(d,e,l,u,h,o){return n(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="das-tragische-schicksal-der-familie-alsberg-–-die-menschlichen-kosten-der-arisierung-und-die-rolle-helmut-hortens" tabindex="-1">Das tragische Schicksal der Familie Alsberg – Die menschlichen Kosten der &quot;Arisierung&quot; und die Rolle Helmut Hortens <a class="header-anchor" href="#das-tragische-schicksal-der-familie-alsberg-–-die-menschlichen-kosten-der-arisierung-und-die-rolle-helmut-hortens" aria-label="Permalink to &quot;Das tragische Schicksal der Familie Alsberg – Die menschlichen Kosten der &quot;Arisierung&quot; und die Rolle Helmut Hortens&quot;">​</a></h1><p>Die Geschichte der Familie Alsberg und ihres einst blühenden Warenhausimperiums ist ein erschütterndes Zeugnis der Verbrechen des Nationalsozialismus und der systematischen Zerstörung jüdischen Lebens und Unternehmertums in Deutschland. Sie illustriert beispielhaft, auf welchem Fundament aus Unrecht und menschlichem Leid der Reichtum mancher Profiteure der NS-Zeit, wie Helmut Horten, aufgebaut wurde. Dieser Artikel beleuchtet die individuellen Schicksale, die wirtschaftliche Enteignung und die tiefgreifenden Auswirkungen, die die nationalsozialistische Ideologie auf das Leben dieser deutschen Bürger hatte.</p><h2 id="die-wurzeln-eines-warenhausriesen-familie-alsberg-und-die-gebruder-alsberg-ag" tabindex="-1">Die Wurzeln eines Warenhausriesen: Familie Alsberg und die &quot;Gebrüder Alsberg AG&quot; <a class="header-anchor" href="#die-wurzeln-eines-warenhausriesen-familie-alsberg-und-die-gebruder-alsberg-ag" aria-label="Permalink to &quot;Die Wurzeln eines Warenhausriesen: Familie Alsberg und die &quot;Gebrüder Alsberg AG&quot;&quot;">​</a></h2><p>Die Familiengeschichte der Alsbergs, die untrennbar mit dem Aufstieg des modernen Warenhauses in Deutschland verbunden ist, beginnt mit <strong>Salomon Alsberg</strong>, einem Kaufmann, der Vater von elf Kindern war. Eines seiner Kinder, <strong>Siegfried Alsberg (1850–1935)</strong>, sollte zum visionären Begründer und Motor eines der bedeutendsten Warenhauskonzerne im Deutschen Reich aufsteigen: der &quot;Gebrüder Alsberg AG&quot; mit Hauptsitz in Köln.</p><p>Unter Siegfried Alsbergs Führung und der Beteiligung seiner Ehefrau <strong>Emma Alsberg (geb. Hess, 1857–1942)</strong> sowie weiterer Familienmitglieder entwickelte sich das Unternehmen zu einem florierenden Imperium. Die Alsberg-Warenhäuser waren bekannt für ihre Qualität, ihr breites Sortiment und ihre innovative Geschäftspraxis. Sie prägten die Innenstädte zahlreicher deutscher Metropolen und Mittelstädte, darunter:</p><ul><li><strong>Bochum:</strong> Mit dem imposanten &quot;Kortumhaus&quot; an der Hochstraße (heute Kortumstraße), erbaut zwischen 1913 und 1921, das erste große Warenhaus der Stadt.</li><li><strong>Duisburg:</strong> Ein Flaggschiff an der Ecke Beekstraße / Universitätsstraße.</li><li><strong>Neuss:</strong> Ein zentraler Anlaufpunkt für Textilien und Mode an der Oberstraße 91.</li><li><strong>Gelsenkirchen:</strong> An der Bahnhofstraße 53 (heute WEKA-Karree) und Gelsenkirchen-Buer.</li><li><strong>Dresden:</strong> An der Wilsdruffer Straße, König-Albert-Passage und Schloßstraße.</li><li><strong>Weitere Standorte:</strong> Osnabrück, Recklinghausen, Witten, Bielefeld, Detmold, Hagen, Hamm, Hildesheim, Iserlohn, Kassel, Koblenz, Lüdenscheid, Mülheim an der Ruhr, Oberhausen, Oldenburg, Remscheid, Solingen, Wanne-Eickel, Wattenscheid und Wuppertal-Elberfeld.</li></ul><p>Diese Präsenz machte die &quot;Gebrüder Alsberg AG&quot; zu einem Eckpfeiler des deutschen Einzelhandels und die Familie Alsberg zu einer angesehenen Größe des Wirtschaftsbürgertums.</p><h2 id="die-arisierung-systematische-enteignung-und-zerstorung-judischen-lebens" tabindex="-1">Die &quot;Arisierung&quot;: Systematische Enteignung und Zerstörung jüdischen Lebens <a class="header-anchor" href="#die-arisierung-systematische-enteignung-und-zerstorung-judischen-lebens" aria-label="Permalink to &quot;Die &quot;Arisierung&quot;: Systematische Enteignung und Zerstörung jüdischen Lebens&quot;">​</a></h2><p>Mit der Machtergreifung der Nationalsozialisten im Januar 1933 begann ein beispielloser Prozess der Verfolgung, Diskriminierung und systematischen Enteignung jüdischer Bürger, der euphemistisch als &quot;Arisierung&quot; bezeichnet wurde. Jüdische Geschäftsleute wurden gezielt unter Druck gesetzt, ihre Unternehmen weit unter Wert zu verkaufen oder zwangsweise aufzugeben. Dies war nicht nur ein wirtschaftlicher Akt, sondern ein brutaler Angriff auf die Existenzgrundlagen und die Würde jüdischer Familien.</p><h3 id="das-fallbeispiel-duisburg-und-die-rolle-helmut-hortens" tabindex="-1">Das Fallbeispiel Duisburg und die Rolle Helmut Hortens <a class="header-anchor" href="#das-fallbeispiel-duisburg-und-die-rolle-helmut-hortens" aria-label="Permalink to &quot;Das Fallbeispiel Duisburg und die Rolle Helmut Hortens&quot;">​</a></h3><p>Ein besonders prägnantes und historisch bedeutsames Beispiel der &quot;Arisierung&quot; betrifft das Alsberg-Warenhaus in <strong>Duisburg</strong>. Am <strong>1. Mai 1938</strong> übernahm der damals erst 27-jährige <strong>Helmut Horten</strong> dieses bedeutende Geschäft der Alsberg-Kette. Diese Transaktion war keine gewöhnliche Geschäftsübernahme unter fairen Marktbedingungen. Sie fand im Kontext massiven staatlichen Drucks, Boykottmaßnahmen und der existenzbedrohenden Lage der jüdischen Eigentümer statt. Horten, der von dieser Politik profitierte, legte mit diesem und ähnlichen &quot;Arisierungen&quot; den Grundstein für sein späteres Warenhausimperium. Sein Reichtum ist somit untrennbar mit dem Unrecht und dem Leid verbunden, das der Familie Alsberg und unzähligen anderen jüdischen Unternehmern im Zuge der &quot;Arisierung&quot; widerfuhr.</p><h2 id="individuelle-schicksale-die-menschliche-tragodie-der-familie-alsberg" tabindex="-1">Individuelle Schicksale: Die menschliche Tragödie der Familie Alsberg <a class="header-anchor" href="#individuelle-schicksale-die-menschliche-tragodie-der-familie-alsberg" aria-label="Permalink to &quot;Individuelle Schicksale: Die menschliche Tragödie der Familie Alsberg&quot;">​</a></h2><p>Das persönliche Leid der Familie Alsberg ging weit über den Verlust ihres Lebenswerks hinaus. Es ist eine Geschichte von Vertreibung, Entwürdigung, Deportation und Ermordung, die das ganze Ausmaß der nationalsozialistischen Verbrechen offenbart.</p><h3 id="siegfried-und-emma-alsberg-die-grundergeneration" tabindex="-1">Siegfried und Emma Alsberg: Die Gründergeneration <a class="header-anchor" href="#siegfried-und-emma-alsberg-die-grundergeneration" aria-label="Permalink to &quot;Siegfried und Emma Alsberg: Die Gründergeneration&quot;">​</a></h3><p><strong>Siegfried Alsberg</strong> verstarb 1935, noch vor den brutalsten Phasen der Verfolgung. Seine Witwe, <strong>Emma Alsberg (geb. Hess)</strong>, geboren am 29. November 1857 in Kempen, erlebte die Eskalation des Terrors. Ihr letzter frei gewählter Wohnsitz war am Stadtwaldgürtel 43 in Köln. Von dort wurde sie am 15. Juni 1942 in das Ghetto Theresienstadt deportiert. Die Bedingungen in Theresienstadt, das als &quot;Vorzeigeghetto&quot; der NS-Propaganda diente, in Wahrheit aber ein Durchgangslager und Sterbelager war, waren unmenschlich. Emma Alsberg verstarb dort am 1. Dezember 1942 im Alter von 85 Jahren an Entkräftung und den Folgen der Haft.</p><h3 id="dr-alfred-alsberg-und-martha-alsberg-das-ende-einer-familie" tabindex="-1">Dr. Alfred Alsberg und Martha Alsberg: Das Ende einer Familie <a class="header-anchor" href="#dr-alfred-alsberg-und-martha-alsberg-das-ende-einer-familie" aria-label="Permalink to &quot;Dr. Alfred Alsberg und Martha Alsberg: Das Ende einer Familie&quot;">​</a></h3><p>Ihr Sohn, der promovierte Jurist und Weltkriegsoffizier <strong>Dr. Alfred Alsberg (geb. 1883)</strong>, war nicht nur Miteigentümer, sondern auch Direktor der Gebrüder Alsberg AG und leitete unter anderem das Geschäft in Bochum (Kortumhaus). Selbst nach der Machtübernahme der Nazis wurde er zunächst noch als Geschäftsführer toleriert, da seine Expertise für den Betrieb unerlässlich war. Doch der Druck wuchs unaufhörlich. Das Kortumhaus wurde 1933/1935 zwangsweise in &quot;Kaufhaus Kortum&quot; umbenannt, um den jüdischen Namen zu tilgen.</p><p>Alfred Alsberg und seine Ehefrau <strong>Martha Alsberg (geb. Eichengrün, 1895–1944)</strong> lebten zuletzt am Morsdorfer Hof 35 in Köln. Im Oktober 1941 wurden sie von dort aus in das Ghetto Litzmannstadt (Łódź) deportiert. In diesem Ghetto herrschten katastrophale Bedingungen. <strong>Alfred Alsberg</strong> verhungerte dort am 14. November 1943. <strong>Martha Alsberg</strong> wurde nach ihrer Deportation aus Litzmannstadt im Jahr 1944 in das Vernichtungslager Kulmhof (Chełmno) gebracht und dort ermordet. Ihr Tod im Vernichtungslager ist ein weiterer Beleg für den systematischen Völkermord der Nationalsozialisten.</p><h3 id="die-uberlebenden-kinder-alfreds-und-marthas-eine-flucht-ins-ungewisse" tabindex="-1">Die überlebenden Kinder Alfreds und Marthas: Eine Flucht ins Ungewisse <a class="header-anchor" href="#die-uberlebenden-kinder-alfreds-und-marthas-eine-flucht-ins-ungewisse" aria-label="Permalink to &quot;Die überlebenden Kinder Alfreds und Marthas: Eine Flucht ins Ungewisse&quot;">​</a></h3><p>Mitten in diesem unermesslichen Leid gab es auch Geschichten des Überlebens, oft durch heroische Anstrengungen oder glückliche Umstände. Drei Kinder von Alfred und Martha Alsberg konnten dem Holocaust entkommen:</p><ul><li><strong>Eva Alsberg (geb. 1924)</strong> gelang die Flucht mit einem Kindertransport nach England. Sie heiratete später den Diplomaten Herbert Samuel Walker. Ihr Schicksal ist auch durch einen Stolperstein vor ihrer ehemaligen Schule, der Königin-Luise-Schule in Köln, verewigt.</li><li>Ihre Brüder <strong>Fritz Alsberg (1920–2009)</strong> und <strong>Heinz Alsberg (1921–2008)</strong> konnten ebenfalls rechtzeitig ins Ausland fliehen und so dem sicheren Tod entgehen.</li></ul><h3 id="die-josephs-familie-in-neuss-eine-ausgeloschte-generation" tabindex="-1">Die Josephs-Familie in Neuss: Eine ausgelöschte Generation <a class="header-anchor" href="#die-josephs-familie-in-neuss-eine-ausgeloschte-generation" aria-label="Permalink to &quot;Die Josephs-Familie in Neuss: Eine ausgelöschte Generation&quot;">​</a></h3><p>Die Tragödie der Alsbergs beschränkte sich nicht nur auf die direkte Gründerfamilie. Eng mit dem Unternehmen verbunden war die <strong>Familie Josephs</strong> in Neuss. Der Geschäftsführer des Kaufhauses Alsberg in Neuss, <strong>Gustav Josephs (geb. 1881)</strong>, war eine prägende Figur des lokalen Wirtschaftslebens. Nach der &quot;Arisierung&quot; des Geschäfts im Jahr 1939 floh er mit seiner Familie in die Niederlande. Doch auch dort waren sie nicht sicher vor der deutschen Besatzung. Die Familie wurde im Durchgangslager Westerbork interniert und von dort aus nach Auschwitz deportiert.</p><ul><li><strong>Gustav Josephs</strong> wurde am 17. September 1942 in Auschwitz ermordet.</li><li>Seine Ehefrau <strong>Käthe Josephs (geb. Felsenthal, 1890)</strong> teilte sein Schicksal und wurde ebenfalls am 17. September 1942 in Auschwitz ermordet.</li><li>Ihre drei Töchter wurden ebenfalls in Auschwitz ermordet: <ul><li><strong>Ruth Josephs (geb. 1921)</strong> am 17. September 1942.</li><li><strong>Lotte Josephs (geb. 1917)</strong> am 30. September 1942.</li><li><strong>Ilse Josephs (geb. 1919)</strong> am 30. September 1942.</li></ul></li></ul><p>Die gesamte Kernfamilie Josephs wurde durch den Holocaust ausgelöscht – ein erschütterndes Beispiel für die Vernichtungsabsicht des Regimes. Ihre Geschichte wird in Neuss durch fünf Stolpersteine vor ihrem letzten frei gewählten Wohnhaus an der Loerickstraße 6 bewahrt, deren Patenschaft von Schülerinnen des Gymnasiums Marienberg übernommen wurde.</p><h3 id="weitere-opfer-aus-dem-erweiterten-kreis" tabindex="-1">Weitere Opfer aus dem erweiterten Kreis <a class="header-anchor" href="#weitere-opfer-aus-dem-erweiterten-kreis" aria-label="Permalink to &quot;Weitere Opfer aus dem erweiterten Kreis&quot;">​</a></h3><p>Auch andere Verwandte der Alsbergs fielen dem Rassenwahn zum Opfer. <strong>Laura Johanna Alsberg (geb. Oppenheim, 1861–1943)</strong>, die Ehefrau von Rudolf Alsberg (einem Verwandten Siegfrieds), lebte zuletzt am Lindenthalgürtel 43 in Köln. Auch sie wurde in das Ghetto Theresienstadt deportiert und dort ermordet. Ihr Schicksal wird ebenfalls durch einen Stolperstein in Köln gewürdigt.</p><p>Zwei weitere Stolpersteine in Neuss erinnern an <strong>Albert Joseph (geb. 1862)</strong> und <strong>Julie Joseph (geb. 1866)</strong> an der Drususallee 81. Auch sie wurden am 22. Juli 1942 nach Theresienstadt deportiert. Albert Joseph verstarb dort am 27. September 1942, Julie Joseph am 9. Januar 1943. Obwohl die direkte Verbindung dieser Josephs zu Gustav Josephs nicht explizit ist, zeugen ihre Schicksale vom breit angelegten Terror gegen die jüdische Bevölkerung.</p><h2 id="erinnerung-mahnung-und-die-aufarbeitung-der-geschichte" tabindex="-1">Erinnerung, Mahnung und die Aufarbeitung der Geschichte <a class="header-anchor" href="#erinnerung-mahnung-und-die-aufarbeitung-der-geschichte" aria-label="Permalink to &quot;Erinnerung, Mahnung und die Aufarbeitung der Geschichte&quot;">​</a></h2><p>Das Gedenken an die Opfer der Familie Alsberg und all jener, die unter der nationalsozialistischen Gewaltherrschaft leiden mussten, ist von immenser Bedeutung. <strong>Stolpersteine</strong>, kleine Messingtafeln im Pflaster vor den letzten frei gewählten Wohnhäusern der Opfer, erinnern heute in Köln (z.B. für Emma Alsberg am Stadtwaldgürtel 43, für Eva Alsberg an der Königin-Luise-Schule, für Laura Johanna Alsberg am Lindenthalgürtel 43, und geplante Steine für Alfred, Martha, Fritz und Heinz Alsberg am Morsdorfer Hof 35 im Juni 2025), in Gelsenkirchen (für Alfred, Emma und Martha Alsberg an der Bahnhofstraße 55–65) und in Neuss (für die Familie Josephs an der Loerickstraße 6 und Drususallee 81) an das Leben und die Ermordung dieser Menschen.</p><p>Ihre Namen sind zudem in den Datenbanken der Holocaust-Gedenkstätten, wie der <strong>Yad Vashem</strong>-Datenbank der Namen der Shoah-Opfer, verewigt. Lokale Initiativen, wie die Forschungen von Schülern der Königin-Luise-Schule in Köln, tragen aktiv dazu bei, diese Geschichten vor dem Vergessen zu bewahren.</p><p>Die Geschichte der Familie Alsberg ist eine eindringliche Erinnerung daran, dass der Reichtum, der durch &quot;Arisierung&quot; erworben wurde, auf Zwang, Leid und Mord gründet. Sie mahnt uns, die Mechanismen solcher Verbrechen zu verstehen, die Rolle der Profiteure kritisch zu hinterfragen und uns aktiv gegen Antisemitismus, Rassismus und jede Form von Diskriminierung zu stellen. Die fortgesetzte Auseinandersetzung mit der Geschichte der Alsbergs ist ein wichtiger Beitrag zur Erinnerungskultur und zur Gestaltung einer verantwortungsvollen Zukunft.</p>',32)])])}const m=r(t,[["render",a]]);export{c as __pageData,m as default};
